@dataclass(frozen=True)
class ClockTime:
    """A local clock time on a day counted from game day (``-1`` is Friday).

    Game day is the kickoff date on the stadium's clock. The time is resolved in
    the zone of the edge it places, through ``LocalTime``, so a time in a DST
    gap is refused rather than shifted.
    """

    day: int
    time: str

    def __post_init__(self) -> None:
        if not _HHMM.fullmatch(self.time):
            raise ValueError(f"clock time {self.time!r} must be a 24-hour HH:MM")

