def _marker_to_dict(marker: NightMarker) -> dict[str, Any]:
    payload: dict[str, Any] = {"night": marker.night}
    payload.update(_edge_to_dict("curfew", marker.curfew))
    payload.update(_edge_to_dict("wake", marker.wake))
    payload["at"] = marker.at
    if marker.released_by is not None:
        payload["released_by"] = marker.released_by
    return payload


def _template_to_dict(template: KickoffBandTemplate) -> dict[str, Any]:
    return {
        "band": template.band,
        "game_type": template.game_type,
        "source": template.source,
        "entries": [_entry_to_dict(entry) for entry in template.entries],
        "nights": [_marker_to_dict(marker) for marker in template.nights],
    }


def _template_from_dict(payload: dict[str, Any]) -> KickoffBandTemplate:
    return KickoffBandTemplate(
        band=payload["band"],
        game_type=payload["game_type"],
        source=payload["source"],
        entries=tuple(
            TemplateEntry(
                id=entry["id"],
                kind=entry["kind"],
                title=entry["title"],
                start=_edge_from_dict("start", entry),
                end=_edge_from_dict("end", entry),
                start_at=entry.get("start_at", "home"),
                end_at=entry.get("end_at"),
                movable=entry.get("movable", False),
            )
            for entry in payload["entries"]
        ),
        nights=tuple(
            NightMarker(
                night=marker["night"],
                curfew=_edge_from_dict("curfew", marker),
                wake=_edge_from_dict("wake", marker),
                at=marker.get("at", "home"),
                released_by=marker.get("released_by"),
            )
            for marker in payload["nights"]
        ),
    )

